/// Initial NFA state for lexical state IN_HASH_RAW_STRING.
fn NfaNameIN_HASH_RAW_STRINGIndex0(ch: u32, next_states: &mut [u64], valid_types: Option<&HashSet<TokenType>>, already_matched: &mut HashSet<TokenType>) -> Option<TokenType> {
    let mut matched_type: Option<TokenType> = None;
    if ch == 34
 {
        bitset_set(next_states, 1);
    }
    if ch <= 1114111
 {
        if valid_types.map_or(true, |vt| vt.contains(&TokenType::ANY_CHAR)) {
            matched_type = Some(TokenType::ANY_CHAR);
        }
    }
    matched_type
}

